"""Helpers shared by integration adapters: YAML sidecars, kit paths, Kanidm URLs, secret refs."""

from __future__ import annotations

from pathlib import Path
from typing import Any

import yaml

SIDECAR_HEADER = (
    "# Generated by easydeploy-engine. Re-apply the engine after domain changes.\n"
    "# Set oidc.managed: false (Kanidm), auth.oidc.managed: false (OpenCloud, Nextcloud),\n"
    "# features.sso.managed: false (Matrix), or identity.managed: false (Stalwart) to ignore.\n"
)

LOCAL_IDPS = frozenset({"kanidm"})
KANIDM_SSO_NAME = "Kanidm"
KANIDM_STATE = ".kanidm-easy-deploy"


def to_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() in {"1", "true", "yes", "y", "on"}


def managed_is_false(section: dict | None) -> bool:
    value = (section or {}).get("managed")
    if value is False:
        return True
    return str(value or "").strip().lower() in {"false", "no", "0"}


def load_yaml(path: Path) -> dict:
    with path.open() as handle:
        data = yaml.safe_load(handle) or {}
    if not isinstance(data, dict):
        raise ValueError(f"{path}: root must be a mapping")
    return data


def write_sidecar(path: Path, data: dict, *, header: str = SIDECAR_HEADER) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    body = yaml.safe_dump(data, default_flow_style=False, sort_keys=False)
    path.write_text(header + body)


def resolve_kit_path(service: dict, project_root: Path) -> Path:
    base = Path(service["path"]).expanduser()
    if not base.is_absolute():
        base = (project_root / base).resolve()
    return base


def deploy_mapping(kit_root: Path, *keys: str) -> dict:
    deploy = kit_root / "deploy.yaml"
    if not deploy.is_file():
        return {}
    data: Any = load_yaml(deploy)
    for key in keys:
        if not isinstance(data, dict):
            return {}
        data = data.get(key) or {}
    return data if isinstance(data, dict) else {}


def read_required_domain(kit_root: Path, label: str, section: str, key: str, placeholder: str) -> str:
    deploy = kit_root / "deploy.yaml"
    if not deploy.is_file():
        raise FileNotFoundError(f"{label} deploy.yaml not found at {deploy}")
    value = str((load_yaml(deploy).get(section) or {}).get(key) or "").strip()
    if not value or value == placeholder:
        raise ValueError(f"{deploy}: {section}.{key} is not set")
    return value


def kanidm_origin(domain: str) -> str:
    return f"https://{str(domain).strip().rstrip('/')}"


def kanidm_issuer_url(domain: str, client_id: str) -> str:
    return f"{kanidm_origin(domain)}/oauth2/openid/{client_id}"


def kanidm_discovery_url(domain: str, client_id: str) -> str:
    return f"{kanidm_issuer_url(domain, client_id)}/.well-known/openid-configuration"


def kanidm_secret_path(kanidm_root: Path, client_id: str) -> Path:
    """Where the Kanidm kit stores a confidential client's secret after it applies."""
    return kanidm_root / KANIDM_STATE / "integration" / "oidc-secrets.d" / f"{client_id}.yaml"


def ldap_base_dn(domain: str) -> str:
    labels = [part for part in str(domain).strip().lower().split(".") if part]
    if not labels:
        raise ValueError("cannot derive LDAP base DN from an empty domain")
    return ",".join(f"dc={label}" for label in labels)


def plaintext_oidc_secret(value: str) -> str:
    secret = str(value or "").strip()
    prefix = "$plaintext$"
    if secret.startswith(prefix):
        return secret[len(prefix) :]
    return secret


def secret_ref(path: Path, key: str) -> dict[str, str]:
    """A pointer a kit resolves at its own apply time: YAML file plus dotted key path.

    Used when the secret does not exist yet when the engine wires sidecars (for
    example a Kanidm client secret, created when the Kanidm kit applies).
    """
    return {"file": str(path), "key": key}


def consumer_should_skip(kit_root: Path, service_entry: dict) -> bool:
    """True when the kit's auth.oidc opts out of engine wiring or names another IdP."""
    if managed_is_false(service_entry.get("oidc") if isinstance(service_entry.get("oidc"), dict) else {}):
        return True
    oidc = deploy_mapping(kit_root, "auth", "oidc")
    if managed_is_false(oidc):
        return True
    provider = str(oidc.get("provider") or "").strip().lower()
    return bool(provider) and provider not in LOCAL_IDPS
